"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10750"],{93805(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.base_legal_do_fada.municipio_invalido","status":422,"titulo":"Munic\xedpio informado \xe9 inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.base_legal_do_fada.municipio_invalido","requisitos":[],"oQueAconteceu":["O cadastro da base legal do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) trouxe um munic\xedpio fora do formato esperado. A resposta indica, em `errors[]`, a posi\xe7\xe3o do item (por exemplo `municipios[2]`), com uma entrada por problema encontrado. Cada munic\xedpio \xe9 conferido por:","- **c\xf3digo IBGE**: obrigat\xf3rio (ausente, vazio ou s\xf3 com espa\xe7os \xe9 recusado), com 7 d\xedgitos e com os dois primeiros correspondendo a uma UF existente;\\n- **nome**: obrigat\xf3rio (ausente, vazio ou s\xf3 com espa\xe7os tamb\xe9m produz o erro), com at\xe9 150 caracteres e sem o caractere nulo (U+0000);\\n- **UF**: obrigat\xf3ria e coerente com a UF do c\xf3digo IBGE, sem distinguir mai\xfasculas e min\xfasculas.","Os espa\xe7os do come\xe7o e do fim do c\xf3digo, do nome e da UF s\xe3o removidos antes da confer\xeancia; por isso o limite de 150 caracteres do nome vale depois dessa remo\xe7\xe3o. Um item nulo na lista (por exemplo `\\"municipios\\": [null]`) \xe9 tratado como munic\xedpio sem nenhum campo e produz os erros de aus\xeancia.","A confer\xeancia \xe9 s\xf3 de formato: o Uni+ n\xe3o consulta o servi\xe7o de geografia para saber se o munic\xedpio existe de fato. Nada foi gravado.","Na atualiza\xe7\xe3o, a base legal \xe9 procurada antes: com um identificador inexistente a resposta \xe9 [base legal n\xe3o encontrada](/erros/uniplus.configuracao.base_legal_do_fada.nao_encontrado)."],"comoResolver":["Corrija o item apontado na resposta: preencha o c\xf3digo IBGE (7 d\xedgitos), o nome e a UF que o c\xf3digo indica, respeitando o limite de tamanho do nome. Se houver mais de um munic\xedpio inv\xe1lido, a resposta lista cada um em `errors[]`."],"ondeAparece":["Cria\xe7\xe3o de uma base legal do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso","Atualiza\xe7\xe3o de uma base legal do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Base legal do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);